// PostgREST returns a JSON array for setof-json RPCs. Normalise to one n8n
// item per row, regardless of how this n8n version wraps the response.
const out = [];
for (const it of $input.all()) {
  const j = it.json;
  if (Array.isArray(j)) { for (const r of j) out.push({ json: r }); }
  else if (j && Array.isArray(j.data)) { for (const r of j.data) out.push({ json: r }); }
  else if (j && j.conversation_id) { out.push({ json: j }); }
}
return out;

const row = $('Fan out slots').item.json;
const ctx = $('agent_context').item.json;
const zone = 'Europe/Lisbon';
const t = DateTime.fromISO(row.slot.start_time).setZone(zone).toFormat('HH:mm');
const clinic = ctx.clinic_name || 'a clínica';
const patient = (row.patient && row.patient.name) || (ctx.patient && ctx.patient.name) || '';
const firstName = patient ? patient.split(' ')[0] : '';
const doctor = (row.slot && row.slot.doctor_name) || '';
// Exact time in code; the model must copy it verbatim.
const facts = 'Consulta de amanhã: às ' + t + (doctor ? (' com ' + doctor) : '') + '.'
  + ' Objetivo: confirmar de forma simpática que o paciente ainda vem, e pedir que avise se não puder.';
const system = 'É rececionista da ' + clinic + ', em Portugal, e escreve como uma pessoa real: cordial, natural e breve. '
  + 'Português europeu formal ("você"). Nunca se apresenta nem inventa um nome. '
  + (firstName ? ('Trate o paciente por "' + firstName + '". ') : '')
  + 'Escreva UMA mensagem curta (1-2 frases) que lembra a consulta de amanhã e pede, de forma natural, '
  + 'que confirme a presença ou avise se não puder vir (por ex. "é só responder-me" ou "diga-me se mantém"). '
  + 'NUNCA imponha um formato rígido tipo "responda SIM ou NÃO". '
  + 'REGRA ABSOLUTA: copie a hora, data e nomes EXATAMENTE como aparecem nos factos; nunca invente nem altere um número. '
  + 'Termine sempre com: Responda STOP para não receber mais mensagens. '
  + 'Responda APENAS com o texto da mensagem.';
return { json: { conversation_id: row.conversation_id, system_prompt: system, user_prompt: facts } };
